// Package icons holds the few Lucide icons that examples/chat uses, as
// tela.Icon variables generated by `tela icons gen` from the SVG files in
// this directory. It is a subset of the separate module
// github.com/kuronosu/tela/icons/lucide (the core module cannot import it),
// with the drawings of lucide-static 1.61.0 and Lucide's license file
// (LICENSE).
//
// To change the set, add or remove SVG files here and run
//
//	go generate ./examples/chat/icons
//
//go:generate go run github.com/kuronosu/tela/cmd/tela icons gen -pkg icons -o . -source "Lucide 1.61.0 (lucide-static, https://lucide.dev)" -license ISC -license-file LICENSE .
package icons
